    abnormal = any(record.get('abnormal_vitals', False) for record in recent_records)
    abnormal_score = 20 if abnormal else 0
    score = age_score + conditions_score + severity_score + abnormal_score
    # Ensure bounds
    score = min(max(score, 0.0), 100.0)
    return score

