class MockPatient:
    def __init__(self, age, total_conditions, average_severity):
        self.age = age
        self._total_conditions = total_conditions
        self._average_severity = average_severity

    def get_total_conditions(self):
        return self._total_conditions

    def get_average_severity(self):
        return self._average_severity


class MockHospital:
    def __init__(self, patients, records):
        # patients: dict {patient_id: MockPatient}
        # records: dict {patient_id: list of record}, record is dict
        self._patients = patients
        self._records = records

    def get_patient(self, patient_id):
        return self._patients[patient_id]

    def get_recent_records(self, patient_id, days):
        # Ignore `days` for mock
        return self._records.get(patient_id, [])

def has_abnormal_vitals(record):
    # Suppose vital values out of [60, 100] are abnormal for 'heart_rate'
    # and out of [36.5, 37.5] for 'temperature' (arbitrary)
    if 'heart_rate' in record:
        hr = record['heart_rate']
        if hr < 60 or hr > 100:
            return True
    if 'temperature' in record:
        temp = record['temperature']
        if temp < 36.5 or temp > 37.5:
            return True
    return False


def patient_risk_score(hospital, patient_id):
    '''
    Calculate risk score using formula: 
    (patient.age / 100 * 30) +
    (patient.get_total_conditions() * 5 * 25/100) + 
    (patient.get_average_severity() * 10 * 25/100) + 
    (20 if recent records have abnormal vitals else 0).
    Returns: float between 0.0 and 100.0.
    '''
    patient = hospital.get_patient(patient_id)
    age_points = (patient.age / 100.0) * 30
    cond_points = patient.get_total_conditions() * 5 * 0.25
    sev_points = patient.get_average_severity() * 10 * 0.25
    recent_records = hospital.get_recent_records(patient_id, 90)
    abn_vitals = any(has_abnormal_vitals(rec) for rec in recent_records)
    abnormal_points = 20 if abn_vitals else 0
    score = age_points + cond_points + sev_points + abnormal_points
    # Clamp score between 0 and 100
    return min(max(score, 0.0), 100.0)

