class DummyPatient:
    def __init__(self, age, conditions, severities):
        self.age = age
        self._conditions = conditions  # list of condition names
        self._severities = severities  # list of severity ints (0-10)

    def get_total_conditions(self):
        return len(self._conditions)

    def get_average_severity(self):
        if not self._severities:
            return 0.0
        return sum(self._severities)/len(self._severities)

class DummyHospital:
    def __init__(self, patients, records_map):
        self._patients = patients  # dict: patient_id -> DummyPatient
        self._records_map = records_map  # dict: patient_id -> list of vital dicts

    def get_patient(self, patient_id):
        return self._patients[patient_id]

    def get_recent_records(self, patient_id, days):
        # days ignored in dummy, just return all records
        return self._records_map.get(patient_id, [])

def patient_risk_score(hospital, patient_id):
    '''
    See prompt
    '''
    patient = hospital.get_patient(patient_id)
    age_score = (patient.age / 100) * 30
    condition_score = patient.get_total_conditions() * 5 * 0.25
    severity_score = patient.get_average_severity() * 10 * 0.25
    records = hospital.get_recent_records(patient_id, 90)
    abnormal = False
    # "abnormal vitals" = any vital <50 or >150 for 'bp' or 'hr'
    for record in records:
        for k, v in record.items():
            if k in ('bp', 'hr') and (v < 50 or v > 150):
                abnormal = True
                break
        if abnormal:
            break
    vital_score = 20 if abnormal else 0
    score = age_score + condition_score + severity_score + vital_score
    return min(100.0, max(0.0, float(round(score, 2))))  # ensure 0-100 range

