def patient_risk_score(hospital, patient_id):
    '''
    As described: returns float between 0.0 and 100.0
    '''
    patient = hospital.get_patient(patient_id)
    if not patient:
        return 0.0 # or maybe raise Exception

    records = hospital.get_recent_records(patient_id, 90)
    # Let's say a record is dict, and abnormal vital means 'abnormal_vital': True
    abnormal_vitals = any(r.get('abnormal_vital', False) for r in records)

    # Formula:
    # (patient.age / 100 * 30) + (patient.get_total_conditions() * 5 * 25/100)
    # + (patient.get_average_severity() * 10 * 25/100)
    # + (20 if recent records have abnormal vitals else 0)
    age_part = (patient.age / 100) * 30
    condition_part = patient.get_total_conditions() * 5 * 0.25
    severity_part = patient.get_average_severity() * 10 * 0.25
    vitals_part = 20 if abnormal_vitals else 0
    score = age_part + condition_part + severity_part + vitals_part
    # Clamp
    if score < 0.0:
        score = 0.0
    if score > 100.0:
        score = 100.0
    return score

