        if not match:
            return None
        if report_type == 'summary':
            return {
                'employee_id': match['employee_id'],
                'overall_rating': match['overall_rating'],
                'goals_status': match['goals_status']
            }
        elif report_type == 'detailed':
            # All fields, types already converted above
            return match
        else:
            # Invalid report_type for employee query
            return None
    else:
        # employee_id is None
        if report_type == 'department':
            # Group by department
            departments = {}
            for row in records:
                dept = row['department']
                overall_rating = row.get('overall_rating', None)
                if overall_rating is None:
                    continue  # skip this if rating is missing
                if dept not in departments:
                    departments[dept] = {'total': 0.0, 'count': 0}
                departments[dept]['total'] += overall_rating
                departments[dept]['count'] += 1
            # Build output dict
            result = {}
            for dept, vals in departments.items():
                avg_rating = vals['total'] / vals['count'] if vals['count'] > 0 else 0.0
                result[dept] = {'avg_rating': avg_rating, 'count': vals['count']}
            return result
        else:
            # Invalid combination: employee_id=None and not department report
            return None

